@MainActor
final class Debouncer {
    private var task: Task<Void, Never>?
    private let delay: Duration
    init(delay: Duration) { self.delay = delay }

    func callAsFunction(_ action: @escaping @MainActor () async -> Void) {
        task?.cancel()
        task = Task {
            try? await Task.sleep(for: delay)
            guard !Task.isCancelled else { return }
            await action()
        }
    }
}

@MainActor
final class Throttler {
    private var last: ContinuousClock.Instant?
    private let interval: Duration
    init(interval: Duration) { self.interval = interval }

    func callAsFunction(_ action: () -> Void) {
        let now = ContinuousClock.now
        if let last, now - last < interval { return }
        last = now
        action()
    }
}

// usage: debounce(searchQuery) { await viewModel.search(query) }
